def process_word(s):
    upper_count = sum(1 for char in s if char.isupper())
    lower_count = len(s) - upper_count

    if upper_count > lower_count:
        return s.upper()
    else:
        return s.lower()

if __name__ == "__main__":
    word = input().strip()
    print(process_word(word))
```

