def max_problems_solved():
    n, k = map(int, input().split())
    total_time_available = 240 - k
    
    def can_solve(m):
        return sum(5 * i for i in range(1, m + 1)) <= total_time_available

    low, high = 0, n
    while low < high:
        mid = (low + high + 1) // 2
        if can_solve(mid):
            low = mid
        else:
            high = mid - 1
    
    print(low)

max_problems_solved()
```

