def main():
    n = int(input())
    points = list(map(int, input().split()))
    
    if n == 1:
        print(0)
        return
    
    best = worst = points[:2]
    amazing_count = 0
    
    for p in points[2:]:
        if p > max(best):
            amazing_count += 1
            best.append(p)
        elif p < min(worst):
            amazing_count += 1
            worst.append(p)

    print(amazing_count)

if __name__ == "__main__":
