def min_moves_to_one(n):
    moves = 0
    while n > 1:
        if n % 6 == 0:
            n //= 6
        elif n % 3 == 0:
            n *= 2
        else:
            return -1
        moves += 1
    return moves

t = int(input())
for _ in range(t):
    n = int(input())
    print(min_moves_to_one(n))
```

