def solve():
    t = int(input())
    for _ in range(t):
        a, b, c = map(int, input().split())
        
        # Check if (2*b - a) > 0 and is divisible by c
        if ((2 * b - a) % c == 0) and ((2 * b - a) > 0):
            print("YES")
        # Check if (c + b) is even, (c + b) / 2 - a > 0 and is divisible by b
        elif (((c + b) // 2) % a == 0) and ((c + b) // 2 > a):
            print("YES")
        # Check if (2 * c - b) is divisible by a and (2 * c - b) > 0
        elif ((2 * c - b) % a == 0) and ((2 * c - b) > 0):
            print("YES")
        else:
            print("NO")

solve()
```

