def solve():
    t = int(input())
    for _ in range(t):
        n, m = map(int, input().split())
        grid = [input() for _ in range(n)]
        
        # Find the first '#' to determine one point on the circle
        for i in range(n):
            for j in range(m):
                if grid[i][j] == '#':
                    x1, y1 = i + 1, j + 1
                    break
            else:
                continue
            break
        
        # Find another '#' to determine another point on the circle
        for i in range(n - 1, -1, -1):
            for j in range(m - 1, -1, -1):
                if grid[i][j] == '#':
                    x2, y2 = i + 1, j + 1
                    break
            else:
                continue
            break
        
        # Calculate the center of the circle using the two points found
        h = (x1 + x2) // 2
        k = (y1 + y2) // 2
        print(h, k)

solve()
```

