def check_intersection(a, b, c, d):
    def between(x, y, z):
        return (y < z and x > y) or (z < y and x < y)
    
    return (between(c, a, d) != between(c, b, d)) and (between(a, c, b) != between(a, d, b))

t = int(input())
for _ in range(t):
    a, b, c, d = map(int, input().split())
    print("YES" if check_intersection(min(a, b), max(a, b), min(c, d), max(c, d)) else "NO")
