def check_intersection(a, b, c, d):
    def ccw(x1, y1, x2, y2, x3, y3):
        return (y2 - y1) * (x3 - x2) > (y3 - y2) * (x2 - x1)

    def intersect(A, B, C, D):
        return ccw(A[0], A[1], C[0], C[1], D[0], D[1]) != ccw(B[0], B[1], C[0], C[1], D[0], D[1]) and ccw(A[0], A[1], B[0], B[1], C[0], C[1]) != ccw(A[0], A[1], B[0], B[1], D[0], D[1])

    def get_point(n):
        import math
        angle = (n - 3) * math.pi / 6
        return (math.cos(angle), math.sin(angle))

    points = [get_point(i) for i in range(1, 13)]
    
    A, B, C, D = points[a-1], points[b-1], points[c-1], points[d-1]
    
    return "YES" if intersect(A, B, C, D) else "NO"

t = int(input().strip())
for _ in range(t):
    a, b, c, d = map(int, input().split())
    print(check_intersection(a, b, c, d))
