def find_min_unique_sum(x):
    digits = list(range(9, 0, -1))
    result = []
    while x > 0 and digits:
        d = min(digits)
        if d <= x:
            result.append(d)
            x -= d
        digits.remove(d)
    
    if x == 0:
        return ''.join(map(str, reversed(result)))
    else:
        return "-1"

t = int(input())
for _ in range(t):
    x = int(input())
    print(find_min_unique_sum(x))
