def solve(x):
    for length in range(1, 10):  # Only need to check up to 9 digits because sum of all distinct digits is 45
        from itertools import permutations
        
        for perm in permutations(range(10), length):
            if sum(perm) == x:
                num = int(''.join(map(str, perm[::-1])))
                if num > 0:  # Ensure it's a positive number
                    return str(num)
    return "-1"

