def sieve(n):
    is_prime = [True] * (n + 1)
    p = 2
    while p * p <= n:
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1
    primes = [p for p in range(2, n + 1) if is_prime[p]]
    return primes

def count_almost_primes(n):
    primes = sieve(n)
    almost_primes = set()
    
    for i in range(len(primes)):
        for j in range(i + 1, len(primes)):
            product = primes[i] * primes[j]
            if product > n:
                break
            almost_primes.add(product)
    
    return len(almost_primes)

n = int(input().strip())
print(count_almost_primes(n))
```

