def find_min_cost(t, cases):
    results = []
    for n, s in cases:
        max_len = 0
        current_len = 1
        
        for i in range(1, n):
            if s[i] != s[i - 1]:
                current_len += 1
            else:
                max_len = max(max_len, current_len)
                current_len = 1

        max_len = max(max_len, current_len)
        results.append(max_len + 1)

    return results

if __name__ == "__main__":
    t = int(input().strip())
    cases = []
    
    for _ in range(t):
        n = int(input().strip())
        s = input().strip()
        cases.append((n, s))
    
    results = find_min_cost(t, cases)
    for result in results:
        print(result)
