def toggle(x, y):
    if 0 <= x < 3 and 0 <= y < 3:
        return (x, y)
    return None

input_matrix = [[int(i) for i in input().split()] for _ in range(3)]

grid = [
    [1, 1, 1],
    [1, 1, 1],
    [1, 1, 1]
]

directions = [(0, 0), (0, -1), (-1, 0), (1, 0), (0, 1)]

for i in range(3):
    for j in range(3):
        for _ in range(input_matrix[i][j]):
            grid[i][j] ^= 1
            for dx, dy in directions:
                pos = toggle(i + dx, j + dy)
                if pos:
                    x, y = pos
                    grid[x][y] ^= 1

for row in grid:
    print(''.join(map(str, row)))
