import sys

def minimum_baking_time():
    input = sys.stdin.read
    data = input().split()
    
    def min_minutes(n):
        if n < 6:
            return 15
        elif n == 6 or n == 7 or n == 8:
            return 30
        else:
            return ((n + 1) // 2) * 5

    t = int(data[0])
    results = []
    
    for i in range(1, t + 1):
        n = int(data[i])
        results.append(min_minutes(n))
        
    sys.stdout.write("\n".join(map(str, results)) + "\n")

minimum_baking_time()
```

